arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B71C1C;
  --red-glow: rgba(230, 57, 70, 0.3);
  --bg: #111111;
  --bg-card: #1A1A1A;
  --bg-elevated: #222222;
  --white: #FFFFFF;
  --gray-100: #F5F5F5;
  --gray-300: #CCCCCC;
  --gray-500: #888888;
  --gray-700: #444444;
  --font-heading: 'Oswald', 'Arial Narrow', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--gray-100);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ─── TOP BAR ─── */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.5px;
}
.top-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 600;
}

/* ─── NAVBAR ─── */
.navbar {
  background: rgba(17,17,17,0.95);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0;
  padding-bottom: 0;
  height: 72px;
}
.navbar__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
}
.navbar__logo span { color: var(--red); }
.navbar__links { display: flex; gap: 28px; align-items: center; }
.navbar__links a {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--gray-300);
  transition: color var(--transition);
  position: relative;
}
.navbar__links a:hover,
.navbar__links a.active { color: var(--white); }
.navbar__links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--red);
}
.navbar__cta {
  display: flex;
  gap: 12px;
  align-items: center;
}
.navbar__cta a {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 10px 20px;
  border-radius: 4px;
  transition: all var(--transition);
}
.navbar__cta .btn-outline {
  border: 1px solid var(--gray-500);
  color: var(--white);
}
.navbar__cta .btn-outline:hover { border-color: var(--white); }
.navbar__cta .btn-red {
  background: var(--red);
  color: var(--white);
}
.navbar__cta .btn-red:hover { background: var(--red-dark); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  z-index: 1001;
}
.hamburger span {
  display: block;
  width: 26px;
  height: 2px;
  background: var(--white);
  transition: all var(--transition);
}
.hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ─── BUTTONS ─── */
.btn {
  display: inline-block;
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 16px 40px;
  border-radius: 4px;
  transition: all var(--transition);
  font-size: 0.95rem;
}
.btn--primary {
  background: var(--red);
  color: var(--white);
}
.btn--primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px var(--red-glow);
}
.btn--outline {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn--outline:hover {
  background: var(--white);
  color: var(--bg);
}
.btn--large {
  padding: 20px 56px;
  font-size: 1.1rem;
}

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: linear-gradient(135deg, #111 0%, #1a0a0a 50%, #111 100%);
}
.hero--small { min-height: 50vh; }
.hero__overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230,57,70,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero__content { position: relative; z-index: 2; max-width: 800px; padding: 0 24px; }
.hero__tag {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
}
.hero__title {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  line-height: 1.1;
  margin-bottom: 24px;
  color: var(--white);
}
.hero__subtitle {
  font-size: 1.15rem;
  color: var(--gray-300);
  max-width: 600px;
  margin: 0 auto 40px;
  line-height: 1.7;
}
.hero__buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── SECTIONS ─── */
.section {
  padding: 100px 0;
}
.section--alt { background: var(--bg-card); }
.section__tag {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 16px;
}
.section__heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  line-height: 1.15;
  margin-bottom: 20px;
  color: var(--white);
}
.section__subheading {
  font-size: 1.05rem;
  color: var(--gray-300);
  max-width: 640px;
  line-height: 1.7;
}
.section__center { text-align: center; }
.section__center .section__subheading { margin: 0 auto; }

/* ─── TWO WAYS GRID ─── */
.two-ways { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; margin-top: 60px; }
.two-ways__card {
  background: var(--bg-elevated);
  border-radius: 12px;
  padding: 48px 40px;
  border: 1px solid rgba(255,255,255,0.06);
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.two-ways__card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.two-ways__card:hover::before { transform: scaleX(1); }
.two-ways__card:hover { border-color: rgba(230,57,70,0.2); }
.two-ways__card h3 {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 8px;
  color: var(--white);
}
.two-ways__card h4 {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
}
.two-ways__card p {
  color: var(--gray-300);
  line-height: 1.7;
}

/* ─── STUDIO EXPERIENCE ─── */
.studio {
  background: linear-gradient(180deg, var(--bg) 0%, #1a0808 50%, var(--bg) 100%);
  text-align: center;
  padding: 120px 0;
}
.studio .section__heading { color: var(--white); }
.studio .section__subheading {
  margin: 0 auto 24px;
  max-width: 640px;
}
.studio__cta-text {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray-500);
  margin-bottom: 32px;
}

/* ─── FREE TRIAL ─── */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,0,0,0.2) 0%, transparent 50%, rgba(0,0,0,0.2) 100%);
}
.free-trial .container { position: relative; z-index: 1; }
.free-trial__heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--white);
  margin-bottom: 32px;
}
.free-trial .btn--outline {
  border-color: var(--white);
  color: var(--white);
}
.free-trial .btn--outline:hover {
  background: var(--white);
  color: var(--red);
}

/* ─── CAROUSEL ─── */
.carousel { overflow: hidden; position: relative; padding: 80px 0; }
.carousel__track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  gap: 20px;
  padding: 0 24px;
}
.carousel__slide {
  min-width: calc(33.333% - 14px);
  border-radius: 12px;
  overflow: hidden;
  background: var(--bg-elevated);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
}
.carousel__slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray-500);
  background: linear-gradient(135deg, var(--bg-elevated), var(--bg-card));
}
.carousel__controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}
.carousel__btn {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 2px solid var(--gray-700);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.2rem;
  transition: all var(--transition);
}
.carousel__btn:hover {
  border-color: var(--red);
  background: rgba(230,57,70,0.1);
}
.carousel__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}
.carousel__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-700);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel__dot.active { background: var(--red); width: 28px; border-radius: 5px; }

/* ─── NEWSLETTER ─── */
.newsletter {
  padding: 80px 0;
  text-align: center;
  border-top: 1px solid rgba(255,255,255,0.06);
}
.newsletter__form {
  display: flex;
  gap: 12px;
  max-width: 500px;
  margin: 32px auto 0;
  justify-content: center;
}
.newsletter__input {
  flex: 1;
  padding: 14px 20px;
  background: var(--bg-elevated);
  border: 1px solid var(--gray-700);
  border-radius: 4px;
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.95rem;
  transition: border-color var(--transition);
}
.newsletter__input:focus {
  outline: none;
  border-color: var(--red);
}
.newsletter__input.error { border-color: #ff4444; }
.newsletter__input.success { border-color: #22c55e; }
.newsletter__msg {
  font-size: 0.85rem;
  margin-top: 10px;
  min-height: 20px;
}
.newsletter__msg--error { color: #ff4444; }
.newsletter__msg--success { color: #22c55e; }

/* ─── FOOTER ─── */
.footer {
  background: #0A0A0A;
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255,255,255,0.06);
}
.footer__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 60px;
}
.footer__col h4 {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
  margin-bottom: 20px;
}
.footer__col a {
  display: block;
  color: var(--gray-500);
  font-size: 0.9rem;
  margin-bottom: 10px;
  transition: color var(--transition);
}
.footer__col a:hover { color: var(--white); }
.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
}
.footer__bottom p {
  color: var(--gray-500);
  font-size: 0.85rem;
}
.country-select {
  background: var(--bg-elevated);
  border: 1px solid var(--gray-700);
  color: var(--gray-300);
  padding: 8px 16px;
  border-radius: 4px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  cursor: pointer;
}
.country-select:focus { outline: none; border-color: var(--red); }

/* ─── WORKOUT PAGE ─── */
.method { text-align: center; }
.method p {
  max-width: 700px;
  margin: 0 auto;
  color: var(--gray-300);
  line-height: 1.8;
  font-size: 1.05rem;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 48px;
}
.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray-500);
  background: var(--bg-elevated);
}
.schedule-table td {
  font-size: 0.95rem;
}
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
}
.schedule-table td:last-child { color: var(--gray-300); }
.schedule-table tr:hover td { background: rgba(230,57,70,0.04); }

.toggle-group {
  display: flex;
  justify-content: center;
  gap: 0;
  margin: 48px auto 40px;
  max-width: 400px;
  border-radius: 6px;
  overflow: hidden;
  border: 2px solid var(--red);
}
.toggle-btn {
  flex: 1;
  padding: 14px 32px;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  color: var(--gray-300);
  background: transparent;
  transition: all var(--transition);
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}
.toggle-btn:hover:not(.active) {
  background: rgba(230,57,70,0.15);
}
.toggle-content {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
  color: var(--gray-300);
  line-height: 1.8;
  font-size: 1.05rem;
}
.toggle-panel { display: none; }
.toggle-panel.active { display: block; animation: fadeIn 0.4s ease; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ─── INSTRUCTORS ─── */
.filter-bar {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--gray-300);
  border: 1px solid var(--gray-700);
  border-radius: 30px;
  transition: all var(--transition);
  font-weight: 500;
}
.filter-btn:hover { border-color: var(--gray-300); color: var(--white); }
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-elevated);
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.06);
  transition: all var(--transition);
  animation: fadeIn 0.4s ease;
}
.instructor-card:hover {
  transform: translateY(-4px);
  border-color: rgba(230,57,70,0.3);
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.instructor-card__img {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-card), var(--bg-elevated));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2.5rem;
  color: var(--red);
  position: relative;
}
.instructor-card__img::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 40%;
  background: linear-gradient(to top, var(--bg-elevated), transparent);
}
.instructor-card__info { padding: 20px 24px; }
.instructor-card__name {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
  margin-bottom: 4px;
}
.instructor-card__location {
  font-size: 0.85rem;
  color: var(--gray-500);
  margin-bottom: 12px;
}
.instructor-card__book {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  font-weight: 600;
  transition: color var(--transition);
}
.instructor-card__book:hover { color: var(--white); }

/* ─── FAQ ACCORDION ─── */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question__icon {
  font-size: 1.4rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.open .faq-question__icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer__inner {
  padding-bottom: 24px;
  color: var(--gray-300);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ─── DIGITAL PLATFORM ─── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  margin-top: 60px;
}
.feature-card {
  background: var(--bg-elevated);
  border-radius: 12px;
  padding: 40px 32px;
  border: 1px solid rgba(255,255,255,0.06);
  transition: all var(--transition);
}
.feature-card:hover {
  border-color: rgba(230,57,70,0.2);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: rgba(230,57,70,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 24px;
}
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 12px;
  color: var(--white);
}
.feature-card p { color: var(--gray-300); line-height: 1.7; font-size: 0.95rem; }

/* ─── COMMUNITY CTA ─── */
.community-promo { text-align: center; }
.community-promo p {
  max-width: 640px;
  margin: 0 auto 32px;
  color: var(--gray-300);
  line-height: 1.8;
  font-size: 1.05rem;
}

/* ─── RESPONSIVE ─── */
@media (max-width: 992px) {
  .navbar__links { display: none; }
  .navbar__cta { display: none; }
  .hamburger { display: flex; }
  .navbar__links.open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100vh;
    background: rgba(17,17,17,0.98);
    justify-content: center;
