cd /app/output && python3 -c "
from html.parser import HTMLParser
import sys, os

class LinkChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if tag == 'a' and 'href' in d:
            h = d['href']
            if h.endswith('.html'):
                self.links.append(h)
        if tag == 'link' and d.get('rel') == 'stylesheet':
            self.links.append(d.get('href',''))
        if tag == 'script' and 'src' in d:
            self.links.append(d['src'])

files = ['index.html','the-workout.html','instructors.html','ride-faq.html','digital-platform.html']
ok = True
for f in files:
    checker = LinkChecker()
    checker.feed(open(f).read())
    for link in checker.links:
        if not os.path.exists(link):
            print(f'MISSING: {f} -> {link}')
            ok = False
if ok:
    print('All internal links and assets resolve correctly.')
"

